const revokeProviderAuthorizationGrant = `-- name: RevokeProviderAuthorizationGrant :execrows
UPDATE authorization_grant
SET revoked_at = now(), revoked_by = $1, updated_at = now()
WHERE id = $2 AND workspace_id = $3
  AND resource_type = 'provider_identity'
  AND created_by = $1
  AND revoked_at IS NULL
`

type RevokeProviderAuthorizationGrantParams struct {
	ActorID     pgtype.UUID `json:"actor_id"`
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

func (q *Queries) RevokeProviderAuthorizationGrant(ctx context.Context, arg RevokeProviderAuthorizationGrantParams) (int64, error) {
	result, err := q.db.Exec(ctx, revokeProviderAuthorizationGrant, arg.ActorID, arg.ID, arg.WorkspaceID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const sumProviderAuthorizationReservations = `-- name: SumProviderAuthorizationReservations :one
SELECT COALESCE(sum(
    CASE
        WHEN context->>'provider_request_tokens' ~ '^[0-9]+$'
        THEN (context->>'provider_request_tokens')::bigint
        ELSE 0::bigint
    END
), 0)::bigint
FROM authorization_audit_event
WHERE workspace_id = $1
  AND action = 'credential.use'
  AND resource_type = 'provider_identity'
  AND resource_id = $2
  AND decision = 'allow'
  AND matched_grant_ids && $3::uuid[]
  AND context->>'provider_budget_reservation' = 'true'
  AND context->>'provider_request_tokens' ~ '^[0-9]+$'
`

type SumProviderAuthorizationReservationsParams struct {
	WorkspaceID pgtype.UUID   `json:"workspace_id"`
	RuntimeID   pgtype.UUID   `json:"runtime_id"`
	GrantIds    []pgtype.UUID `json:"grant_ids"`
}

func (q *Queries) SumProviderAuthorizationReservations(ctx context.Context, arg SumProviderAuthorizationReservationsParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumProviderAuthorizationReservations, arg.WorkspaceID, arg.RuntimeID, arg.GrantIds)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}
